{"code":"import os, glob

log_dir = os.path.expanduser("~/.hermes/cron/output/")
job_ids = ['cf9aad854695', '9b495eddc7e8', '23e92a9bbac9', '2d40869fb8b3', '0bf0a3a2a078']

for jid in job_ids:
    dirpath = os.path.join(log_dir, jid)
    if os.path.isdir(dirpath):
        files = glob.glob(os.path.join(dirpath, "**/*"), recursive=True)
        print(f"\n=== Job {jid}: {files[:10]} ===")
        for fp in files[:3]:
            if os.path.isfile(fp):
                try:
                    with open(fp, 'r') as f:
                        content = f.read()
                    print(f"  -- {fp} (len={len(content)}) --")
                    print(content[:1500])
                except Exception as e:
                    print(f"  -- {fp}: Error reading: {e} --")
